<section class="page-hero"><div class="container"><p class="section-label">Knowledge</p><h1>Insights & Updates</h1></div></section><section class="page-section"><div class="container card-grid card-grid--articles"><?php foreach ($articles as $article): ?><article class="article-card"><?php if (!empty($article['cover_path'])): ?><img src="<?= htmlspecialchars($article['cover_path'], ENT_QUOTES, 'UTF-8') ?>" alt=""><?php else: ?><div class="article-card__placeholder"></div><?php endif; ?><div class="article-card__content"><p class="section-label"><?= htmlspecialchars(date('d M Y', strtotime($article['published_at'])), ENT_QUOTES, 'UTF-8') ?></p><h3><a href="/insights/<?= rawurlencode($article['slug']) ?>"><?= htmlspecialchars($article['title'], ENT_QUOTES, 'UTF-8') ?></a></h3><p><?= htmlspecialchars($article['excerpt'] ?? '', ENT_QUOTES, 'UTF-8') ?></p></div></article><?php endforeach; ?></div></section>